import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect, waitFor } from 'storybook/test';
import InvestigationVault from './InvestigationVault';
import type { InvestigationModel } from '../lib/investigationModel';
// Generated by Frame.pkl from the case's evidence. Nothing in this file states
// a score, a digest or a verdict.
import frame from '../lesson-farms/rails-claims/cases/fddf74bea9/frame.json';

// CIT-395: the sketch in the issue drew a reviewer's view of commit fddf74bea9
// with a Jev score, Peek buttons and a payload digest, all invented. This is the
// same view drawn from evidence only: the commit message from git, Vale's
// alerts on it, the Jev payloads pinned by digest, and whatever recordings and
// snapshots exist. Where the sketch drew a value nobody has produced yet, the
// frame says so instead of showing one. The second story marks each sketch
// element against the same evidence.

type Claim = (typeof frame.claims)[number];
type Element = { claim: string; status: 'proven' | 'unproven' | 'contradicted'; evidence: string };

const model = frame.model as InvestigationModel;
const elements = frame.elements as Record<string, Element>;

const meta = {
  title: 'Investigations/Rails commit claims',
  component: InvestigationVault,
  parameters: { layout: 'padded' },
  args: { model },
} satisfies Meta<typeof InvestigationVault>;
export default meta;
type Story = StoryObj<typeof meta>;

const text = (root: Element | null, selector: string) =>
  (root?.querySelector(selector)?.textContent ?? '').replace(/\u00a0/g, ' ');
// Monaco runs a CodeLens on mouseup, so a plain click() is not enough.
const press = (el: Element) => {
  for (const type of ['mousedown', 'mouseup', 'click']) el.dispatchEvent(new MouseEvent(type, { bubbles: true, cancelable: true }));
};
const lens = (root: Element, label: string) => waitFor(() => {
  const found = Array.from(root.querySelectorAll('.codelens-decoration a, .codelens-decoration span')).find((a) => a.textContent?.includes(label));
  if (!found) throw new Error(`lens "${label}" not shown`);
  return found;
});
const short = (c: Claim) => c.digest.slice(0, 19);

export const TheFrameTheEvidenceSupports: Story = {
  name: 'fddf74bea9: the frame the evidence supports',
  play: async ({ canvasElement, step }) => {
    const [subject] = model.documents[0].text.split('\n');

    await step("the editor shows the author's commit message", async () => {
      await waitFor(() => expect(text(canvasElement, '.view-lines')).toContain(subject));
    });

    await step('Vale flags every absolute claim, including one the sketch did not draw', async () => {
      await waitFor(() => expect(canvasElement.querySelectorAll('.squiggly-warning').length).toBe(frame.claims.length));
    });

    await step('no claim has a Jev score: each lens names the payload with no recording', async () => {
      for (const c of frame.claims) await lens(canvasElement, `${c.word} · Jev: no recording for ${short(c)}`);
    });

    await step('no Peek states: nothing has produced the snapshots', async () => {
      for (const c of frame.claims) await lens(canvasElement, `${c.word} · Peek: no snapshots`);
    });

    const always = frame.claims.find((c) => c.word === 'always')!;
    await step('the lens opens the payload that would be sent, pinned by its digest', async () => {
      press(await lens(canvasElement, `always · Jev: no recording`));
      await waitFor(() => expect(text(canvasElement, '[data-testid="investigation-path"]')).toContain(`jev payload  ›  ${short(always)}`));
      await waitFor(() => expect(text(canvasElement, '.view-lines')).toContain('"type": "noul"'));
      await lens(canvasElement, 'pinned before the call · not sent yet');
    });
  },
};

const STATUS_COLOR: Record<Element['status'], string> = { proven: '#2ea043', unproven: '#9a6700', contradicted: '#cf222e' };

function SketchMarked() {
  return (
    <div style={{ font: '13px system-ui, sans-serif', maxWidth: 820 }}>
      <table data-testid="sketch-elements" style={{ borderCollapse: 'collapse', width: '100%' }}>
        <thead>
          <tr style={{ textAlign: 'left', borderBottom: '1px solid #ccc' }}>
            <th>Sketch element</th><th>What it claims</th><th>Status</th><th>Evidence</th>
          </tr>
        </thead>
        <tbody>
          {Object.entries(elements).map(([id, e]) => (
            <tr key={id} data-element={id} style={{ borderBottom: '1px solid #eee', verticalAlign: 'top' }}>
              <td><code>{id}</code></td>
              <td>{e.claim}</td>
              <td data-status={e.status} style={{ color: STATUS_COLOR[e.status], fontWeight: 600 }}>{e.status}</td>
              <td>{e.evidence}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <p style={{ marginTop: 12, fontWeight: 600 }}>In the evidence, not in the sketch</p>
      <ul data-testid="sketch-undrawn">{frame.undrawn.map((u) => <li key={u}>{u}</li>)}</ul>
    </div>
  );
}

export const TheSketchMarked: Story = {
  name: 'fddf74bea9: the sketch, marked',
  render: () => <SketchMarked />,
  play: async ({ canvasElement, step }) => {
    await step('every sketch element is marked against the evidence', async () => {
      const rows = canvasElement.querySelectorAll('[data-testid="sketch-elements"] tbody tr');
      await expect(rows.length).toBe(Object.keys(elements).length);
    });
    await step('the score and the Peek states are unproven, the drawn digest is contradicted', async () => {
      const status = (id: string) => canvasElement.querySelector(`[data-element="${id}"] [data-status]`)?.textContent;
      await expect(status('p4')).toBe('unproven');
      await expect(status('by/bn')).toBe('unproven');
      await expect(status('r3')).toBe('contradicted');
    });
  },
};
